--!strict
local Config=require(game:GetService("ReplicatedStorage").Modules.QuestConfig);local Profiles=require(script.Parent.PlayerProfileService);local remotes=require(script.Parent.RemoteService).Ensure();local Service={}
local function ensure(p:Player)local profile=Profiles.GetProfile(p);if not profile then return nil end;local day=math.floor(os.time()/86400);local q=profile.DailyQuests;if q.DateKey~=day then local ids={};for id,d in Config do if d.IsEnabled then table.insert(ids,id)end end;table.sort(ids);local selected={};for i=1,math.min(3,#ids)do table.insert(selected,ids[((day+i-2)%#ids)+1])end;q.DateKey=day;q.QuestIds=selected;q.Progress={};q.Claimed={};Profiles.MarkDirty(p)end;return q end
function Service.Snapshot(p:Player):any local q=ensure(p);if not q then return nil end;local list={};for _,id in q.QuestIds do local d=Config[id];table.insert(list,{id=id,name=d.DisplayName,description=d.Description,target=d.Target,reward=d.RewardCoins,progress=q.Progress[id]or 0,claimed=q.Claimed[id]==true})end;return{dateKey=q.DateKey,quests=list}end
function Service.Progress(p:Player,event:string,amount:number?)local q=ensure(p);if not q then return end;for _,id in q.QuestIds do local d=Config[id];if d.ProgressEvent==event and not q.Claimed[id]then q.Progress[id]=math.min(d.Target,(q.Progress[id]or 0)+(amount or 1));Profiles.MarkDirty(p)end end;remotes.QuestUpdated:FireClient(p,Service.Snapshot(p))end
function Service.Claim(p:Player,id:string):(boolean,string)local q=ensure(p);local d=Config[id];if not q or not d or not table.find(q.QuestIds,id)or q.Claimed[id]or(q.Progress[id]or 0)<d.Target then return false,"尚未完成"end;q.Claimed[id]=true;Profiles.IncrementValue(p,"Economy.Coins",d.RewardCoins);Profiles.IncrementValue(p,"Economy.LifetimeCoins",d.RewardCoins);Profiles.MarkDirty(p);remotes.QuestUpdated:FireClient(p,Service.Snapshot(p));return true,"已領取 +"..d.RewardCoins.." Coins"end
return Service
